effect.shader:
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

void main() {
    float faixa = floor(acScreenNorm.y * float(int(rows)));
    float semente = floor(acTime * rate) + faixa;
    float sorteio = hash21(vec2(semente, 7.3));
    float ligada = step(1.0 - density, sorteio);
    float d = (hash21(vec2(semente, 11.7)) - 0.5) * 2.0 * maxShift * ligada;

    float r = texture(inputImg, acScreenNorm + vec2(d, 0.0)).r;
    float g = texture(inputImg, acScreenNorm).g;
    float b = texture(inputImg, acScreenNorm - vec2(d, 0.0)).b;
    float a = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(r, g, b, a);
}
